import{_ as e,o as r,c as i,a5 as t}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"疑問から選ぶ読み順","description":"","frontmatter":{"title":"疑問から選ぶ読み順","study":{"source":"統合ガイド","status":"published","generated":true,"catalog":true,"section":"learning","format":"path","domain":"guide","collection":"questions","order":0,"summary":"整数・浮動小数点、文字コード、メモリ確保、起動、同期、ファイルI/Oとマッピング、アセットロード、DNS・TCP・HTTP・TLS通信、入力と描画、Webの疑問から本文をたどる。"}},"headers":[],"relativePath":"guide/learning-paths.md","filePath":"guide/learning-paths.md"}'),l={name:"guide/learning-paths.md"};function o(s,a,h,d,n,u){return r(),i("div",null,[...a[0]||(a[0]=[t('<div id="読み進め方" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="疑問から選ぶ読み順" tabindex="-1">疑問から選ぶ読み順 <a class="header-anchor" href="#疑問から選ぶ読み順" aria-label="Permalink to &quot;疑問から選ぶ読み順&quot;">​</a></h1><p>辞典を最初から順番に読む必要はありません。いまの疑問に関係する本文から選びます。</p><h2 id="整数はメモリにどう並ぶか" tabindex="-1">整数はメモリにどう並ぶか <a class="header-anchor" href="#整数はメモリにどう並ぶか" aria-label="Permalink to &quot;整数はメモリにどう並ぶか&quot;">​</a></h2><ol><li><a href="/study/data/integer-bits-and-bytes.html">整数をビット列・16進数・バイト列で読む</a>で、値、表記、符号の解釈、バイト順を分ける。</li><li><a href="/study/practice/data/integer-byte-observation.html">C++の整数・バイト列観察サンプル</a>で、型の幅と実メモリ、明示的なLE/BE形式を比較する。</li><li><a href="/study/runtime/cpp-internals/memory-layout.html">メモリレイアウトとアラインメント</a>で、オブジェクトを置く場所やパディングとの違いを調べる。</li></ol><h2 id="floatで小さな差が消えるのはなぜか" tabindex="-1">floatで小さな差が消えるのはなぜか <a class="header-anchor" href="#floatで小さな差が消えるのはなぜか" aria-label="Permalink to &quot;floatで小さな差が消えるのはなぜか&quot;">​</a></h2><ol><li><a href="/study/data/floating-point-spacing.html">floatが表せる値と丸め</a>で、binary32の有効精度、表現できる値の間隔、丸めを調べる。</li><li><a href="/study/practice/data/float-spacing-observation.html">C++のfloat観察サンプル</a>で、ビット表現、隣接値、2の冪の境界、epsilonの意味を確かめる。</li><li><a href="/study/math/rendering/transform.html">座標変換</a>と<a href="/study/math/rendering/camera.html">カメラ・深度</a>で、描画で数値の尺度を扱う場面へつなぐ。</li></ol><h2 id="floatを等しいと判定するには" tabindex="-1">floatを等しいと判定するには <a class="header-anchor" href="#floatを等しいと判定するには" aria-label="Permalink to &quot;floatを等しいと判定するには&quot;">​</a></h2><ol><li><a href="/study/math/floating-point-comparison.html">浮動小数点の比較と許容差</a>で、厳密な等値と近似一致、単位を持つ絶対許容差と無次元の相対許容差を分ける。</li><li><a href="/study/practice/math/float-comparison-observation.html">C++・C#の比較サンプル</a>で、境界・NaN・Inf・非推移性・保存時に失われた座標差を確かめる。</li><li>表現できる値の間隔から調べたい場合は<a href="/study/data/floating-point-spacing.html">floatの刻み幅</a>へ戻る。</li></ol><h2 id="文字はどのようにバイト列になるか" tabindex="-1">文字はどのようにバイト列になるか <a class="header-anchor" href="#文字はどのようにバイト列になるか" aria-label="Permalink to &quot;文字はどのようにバイト列になるか&quot;">​</a></h2><ol><li><a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>で、コードポイント、UTF-8／UTF-16のコード単位、バイト列を分ける。</li><li><a href="/study/practice/data/unicode-observation.html">C++・C#の文字列観察サンプル</a>で、日本語・絵文字・結合文字の表現と、長さの数え方を比べる。</li><li><a href="/study/data/integer-bits-and-bytes.html">整数とバイト列</a>のエンディアンと結び付け、ファイルやAPIの文字コードを確認する。</li></ol><h2 id="「確保する」と内部で何が起きるか" tabindex="-1">「確保する」と内部で何が起きるか <a class="header-anchor" href="#「確保する」と内部で何が起きるか" aria-label="Permalink to &quot;「確保する」と内部で何が起きるか&quot;">​</a></h2><ol><li><a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域期間・スコープ・寿命</a>を区別する。</li><li><a href="/study/runtime/memory/allocation-journey.html">malloc/newの内部</a>で、空き領域の再利用、必要時のOS要求、構築・破棄を追う。</li><li><a href="/study/os/virtual-memory.html">仮想メモリ</a>で、アドレス空間、ページ、予約・コミット・常駐、ページフォルトを区別する。</li><li><a href="/study/practice/memory/windows-memory-observation.html">Windows/C++の観察サンプル</a>で、予約・コミット・初回書込み・解放を実際に分けて確かめる。</li><li><a href="/study/runtime/memory/allocators-and-pools.html">用途別アロケータ</a>、<a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a>、<a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性</a>へ進む。</li></ol><h2 id="ソースコードがcpuで動くまで" tabindex="-1">ソースコードがCPUで動くまで <a class="header-anchor" href="#ソースコードがcpuで動くまで" aria-label="Permalink to &quot;ソースコードがCPUで動くまで&quot;">​</a></h2><ol><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ビルドの旅</a>でコンパイルとリンクをたどる。</li><li><a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位・ヘッダー</a>、<a href="/study/runtime/cpp-internals/symbols-and-linkage.html">シンボル・ABI</a>、<a href="/study/runtime/cpp-internals/object-files-and-libraries.html">実行ファイル・ライブラリ</a>を調べる。</li><li><a href="/study/os/process-startup.html">実行ファイルを起動してmainへ到達するまで</a>で、プロセス・スレッド、ローダー、CRTの役割を分ける。</li><li><a href="/study/practice/process/windows-process-observation.html">Windows/C++のプロセス観察</a>で、main前の記録、親子プロセス、ワーカースレッドのPID・TIDを確かめる。</li><li><a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出し・レジスタ</a>へ進む。</li></ol><h2 id="スレッド間でデータを安全に共有するには" tabindex="-1">スレッド間でデータを安全に共有するには <a class="header-anchor" href="#スレッド間でデータを安全に共有するには" aria-label="Permalink to &quot;スレッド間でデータを安全に共有するには&quot;">​</a></h2><ol><li><a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>で、共有状態と不変条件、同じロックで守る範囲、データを受け渡す順序を調べる。</li><li><a href="/study/practice/threads/inventory-synchronization.html">C++・C#の在庫消費サンプル</a>で、確認と消費、Snapshot、終了待ちと寿命を確かめる。</li><li><a href="/study/runtime/memory/concurrency-bugs.html">並行処理のバグ</a>で、データ競合・競合状態・false sharingの違いを調べる。</li></ol><h2 id="ワーカーで準備したアセットを描画側へ渡すには" tabindex="-1">ワーカーで準備したアセットを描画側へ渡すには <a class="header-anchor" href="#ワーカーで準備したアセットを描画側へ渡すには" aria-label="Permalink to &quot;ワーカーで準備したアセットを描画側へ渡すには&quot;">​</a></h2><ol><li><a href="/study/runtime/bounded-worker-queues.html">容量を決めたワーカーキュー</a>で、満杯や空で待つ条件、受付の終了と回収の順番を調べる。</li><li><a href="/study/game/asset-worker-handoff.html">アセットをワーカーから描画側へ渡す設計</a>で、世代の確認、登録する側の責任、CPUとGPUそれぞれの完了を追う。</li><li><a href="/study/practice/threads/asset-worker-handoff-observation.html">C++のワーカー受け渡し実践</a>で、結果キューを回収し、古い世代を捨てて終了する。</li><li><a href="/study/graphics/optimization/parallel-command-recording.html">D3D12の並列コマンド記録</a>で、描画コマンド自体を複数スレッドで記録するときの提出順と寿命を調べる。</li></ol><h2 id="d3d12でコマンドを記録し、依存する処理を実行するには" tabindex="-1">D3D12でコマンドを記録し、依存する処理を実行するには <a class="header-anchor" href="#d3d12でコマンドを記録し、依存する処理を実行するには" aria-label="Permalink to &quot;D3D12でコマンドを記録し、依存する処理を実行するには&quot;">​</a></h2><ol><li><a href="/study/graphics/optimization/d3d12-resource-barriers.html">D3D12のリソースバリア</a>で、コピーから読み取りへの遷移やUAV・エイリアシングの依存関係を調べる。</li><li><a href="/study/practice/graphics/parallel-command-recording-observation.html">C++の並列コマンド記録実践</a>で、CPUがリストを閉じた順番と、一つのキューへの提出順を変えて確かめる。</li><li><a href="/study/graphics/optimization/gpu-queue-synchronization.html">D3D12のキュー間同期</a>で、コピーと描画を別のキューに分けるときのフェンスと状態を追う。</li><li><a href="/study/graphics/optimization/d3d12-descriptor-heaps.html">D3D12のディスクリプターヒープ</a>で、シェーダーへ渡す参照と、その参照を再利用する条件を調べる。</li></ol><h2 id="描いた画像を次のパスで使うには" tabindex="-1">描いた画像を次のパスで使うには <a class="header-anchor" href="#描いた画像を次のパスで使うには" aria-label="Permalink to &quot;描いた画像を次のパスで使うには&quot;">​</a></h2><ol><li><a href="/study/graphics/postprocess/render-to-texture.html">テクスチャに描き、次のパスで読む</a>で、中間画像をRTVとして書き、SRVとして読む流れを追う。</li><li><a href="/study/practice/graphics/render-to-texture-observation.html">C++の2パス描画実践</a>で、色を入れ替える前後の全画素を読み戻す。</li><li><a href="/study/graphics/postprocess/ping-pong-and-history.html">ピンポンバッファとフレーム履歴</a>で、後処理をつなぐときと前フレームの結果を残すときの違いを調べる。</li><li><a href="/study/graphics/optimization/render-pass-attachments.html">描画パスのアタッチメント</a>で、どの画像を残すか、いつ破棄や再利用ができるかを追う。</li></ol><h2 id="ファイルを読むと内部で何が起きるか" tabindex="-1">ファイルを読むと内部で何が起きるか <a class="header-anchor" href="#ファイルを読むと内部で何が起きるか" aria-label="Permalink to &quot;ファイルを読むと内部で何が起きるか&quot;">​</a></h2><ol><li><a href="/study/os/file-read-journey.html">ファイルを読む仕組み</a>で、アプリのバッファ、OSのファイルキャッシュ、ストレージへの要求を分ける。</li><li><a href="/study/practice/io/file-read-observation.html">C++・C#の読み取り観察</a>で、要求数と実読取数、ファイル位置、EOF、seek、失敗を確かめる。</li><li>テキストとして解釈するときは<a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>へ進む。</li></ol><h2 id="ファイルを読む処理と、ディスクへの要求を計測で分けるには" tabindex="-1">ファイルを読む処理と、ディスクへの要求を計測で分けるには <a class="header-anchor" href="#ファイルを読む処理と、ディスクへの要求を計測で分けるには" aria-label="Permalink to &quot;ファイルを読む処理と、ディスクへの要求を計測で分けるには&quot;">​</a></h2><ol><li><a href="/study/os/windows-file-cache.html">Windowsのファイルキャッシュと先読み</a>で、同じ範囲の再読み取りと先読みでI/Oの量が変わる理由を調べる。</li><li><a href="/study/tools/windows/file-io-tracing.html">ProcmonとWPRでファイルI/Oを追う</a>で、ファイル操作とディスク要求をどのツールで見るか決める。</li><li><a href="/study/practice/io/file-io-trace-observation.html">ファイル読み取りをトレースするC++実践</a>で、同じファイルを2回読み、バイト数と記録を照合する。</li></ol><h2 id="i-oの完了を待ちながら、別の処理を進めるには" tabindex="-1">I/Oの完了を待ちながら、別の処理を進めるには <a class="header-anchor" href="#i-oの完了を待ちながら、別の処理を進めるには" aria-label="Permalink to &quot;I/Oの完了を待ちながら、別の処理を進めるには&quot;">​</a></h2><ol><li><a href="/study/os/asynchronous-file-io.html">非同期I/O</a>で、要求の発行と完了、即時完了、待機と継続、バッファの寿命を分ける。</li><li><a href="/study/practice/io/async-file-read-observation.html">C++・C#の同期・非同期比較</a>で、同じファイルを読み、完了結果と内容の一致を確かめる。</li><li>複数の処理から状態を共有するときは<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>も確認する。</li></ol><h2 id="windowsでi-oの完了をまとめて受け取り、安全に終了するには" tabindex="-1">WindowsでI/Oの完了をまとめて受け取り、安全に終了するには <a class="header-anchor" href="#windowsでi-oの完了をまとめて受け取り、安全に終了するには" aria-label="Permalink to &quot;WindowsでI/Oの完了をまとめて受け取り、安全に終了するには&quot;">​</a></h2><ol><li><a href="/study/os/io-completion-ports.html">I/O完了ポート</a>で、完了キーと要求ポインター、発行時の失敗と完了時の失敗を分ける。</li><li><a href="/study/practice/io/iocp-observation.html">C++のIOCP観察例</a>で、一つのファイルに出した2件の要求をポートから受け取る。</li><li><a href="/study/os/cancelling-overlapped-io.html">非同期I/Oのキャンセル</a>で、停止を要求してから完了を回収し、バッファを解放する順序を確認する。</li></ol><h2 id="ゲームのセーブデータをファイルに保存するには" tabindex="-1">ゲームのセーブデータをファイルに保存するには <a class="header-anchor" href="#ゲームのセーブデータをファイルに保存するには" aria-label="Permalink to &quot;ゲームのセーブデータをファイルに保存するには&quot;">​</a></h2><ol><li><a href="/study/os/file-write-and-durability.html">ファイルの書き込みと永続化</a>で、書き込み成功、読み手への公開、停電後の復旧を別々に考える。</li><li>読み戻し側は<a href="/study/os/file-read-journey.html">ファイルを読む仕組み</a>で、短い読み取りやEOFと、ファイルの形式の検査を区別する。</li></ol><h2 id="ファイルをメモリへのアクセスとして読むには" tabindex="-1">ファイルをメモリへのアクセスとして読むには <a class="header-anchor" href="#ファイルをメモリへのアクセスとして読むには" aria-label="Permalink to &quot;ファイルをメモリへのアクセスとして読むには&quot;">​</a></h2><ol><li><a href="/study/os/memory-mapped-files.html">メモリマップドファイル</a>で、ファイル内位置と仮想アドレス、ページフォルト、ビューの寿命を分ける。</li><li><a href="/study/practice/io/mapped-file-observation.html">C++・C#の読み取り専用マッピング</a>で、通常のreadと内容を照合し、整列した位置と使いたい範囲の対応を確かめる。</li><li>アドレス変換の基礎は<a href="/study/os/virtual-memory.html">仮想メモリ</a>、実行時の組立ては<a href="/study/game/asset-loading.html">アセットロード設計</a>へ進む。</li></ol><h2 id="アセットが読み終わってから、ゲームで使えるまで" tabindex="-1">アセットが読み終わってから、ゲームで使えるまで <a class="header-anchor" href="#アセットが読み終わってから、ゲームで使えるまで" aria-label="Permalink to &quot;アセットが読み終わってから、ゲームで使えるまで&quot;">​</a></h2><ol><li><a href="/study/game/asset-loading.html">アセットロード設計</a>で、読み取り、展開・検証、登録、利用可能化、解放を分ける。</li><li><a href="/study/practice/assets/asset-lifecycle-model.html">C++・C#の状態と寿命のモデル</a>で、古い要求の完了、キャンセル、失敗を含む所有権の移動を確かめる。</li><li>実I/Oの完了待ちは<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>、共有するキューや状態の保護は<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>も確認する。</li><li>Windows PCの<a href="/study/game/directstorage.html">DirectStorage</a>で、読み取りの一括発行、展開、GPUが結果を使えるまでの条件を確認する。</li></ol><h2 id="ゲームの素材をまとめて配布し、必要な範囲だけ読むには" tabindex="-1">ゲームの素材をまとめて配布し、必要な範囲だけ読むには <a class="header-anchor" href="#ゲームの素材をまとめて配布し、必要な範囲だけ読むには" aria-label="Permalink to &quot;ゲームの素材をまとめて配布し、必要な範囲だけ読むには&quot;">​</a></h2><ol><li><a href="/study/game/asset-pack-files.html">アセットパック</a>で、名前、目次、格納位置、圧縮の単位を分ける。</li><li><a href="/study/data/binary-file-validation.html">バイナリファイルの範囲検査</a>で、件数や長さを読み取り・確保に使う前の検査を確かめる。</li><li><a href="/study/practice/io/asset-pack-observation.html">C++でアセットパックを作る実践</a>で、1件の素材を取り出し、壊れた索引が拒否されるところを試す。</li><li><a href="/study/game/asset-build-and-patches.html">アセットビルドと差分配信</a>で、読み込みやすい配置と更新で再利用できる配信単位を考える。</li></ol><h2 id="テクスチャのファイルを読み、gpuで使えるようにするには" tabindex="-1">テクスチャのファイルを読み、GPUで使えるようにするには <a class="header-anchor" href="#テクスチャのファイルを読み、gpuで使えるようにするには" aria-label="Permalink to &quot;テクスチャのファイルを読み、GPUで使えるようにするには&quot;">​</a></h2><ol><li><a href="/study/graphics/texture/dds-and-subresources.html">DDSとサブリソース</a>で、テクスチャの形式、mip、配列スライスからファイル内の位置を求める。</li><li><a href="/study/graphics/texture/d3d12-texture-upload.html">D3D12でテクスチャを転送する流れ</a>で、行の再配置、コピー、リソースの状態とフェンスを追う。</li><li><a href="/study/practice/graphics/dds-upload-observation.html">C++のDDS転送実践</a>で、2つのmipをD3D12へコピーし、読み戻したバイトを照合する。</li><li><a href="/study/graphics/texture/texture-streaming-and-mip-residency.html">テクスチャストリーミング</a>で、先に使える解像度と、メモリに置く範囲を決める。</li></ol><h2 id="_3dモデルのファイルから三角形を描くには" tabindex="-1">3Dモデルのファイルから三角形を描くには <a class="header-anchor" href="#_3dモデルのファイルから三角形を描くには" aria-label="Permalink to &quot;3Dモデルのファイルから三角形を描くには&quot;">​</a></h2><ol><li><a href="/study/graphics/mesh/gltf-mesh-buffers.html">glTFのメッシュデータ</a>で、buffer、bufferView、accessorをたどって頂点とインデックスの位置を求める。</li><li><a href="/study/graphics/mesh/vertex-and-index-input.html">頂点入力とインデックス描画</a>で、バッファの配置と頂点シェーダーの入力をつなぐ。</li><li><a href="/study/practice/graphics/glb-mesh-observation.html">GLBから三角形を描くC++実践</a>で、ファイルを作り、WARPで描いた色を読み戻す。</li><li><a href="/study/graphics/mesh/mesh-import-and-cooking.html">メッシュのインポートとクック</a>で、座標系、マテリアル、描画範囲、実行時のバッファ配置を決める。</li></ol><h2 id="入力からゲーム画面まで" tabindex="-1">入力からゲーム画面まで <a class="header-anchor" href="#入力からゲーム画面まで" aria-label="Permalink to &quot;入力からゲーム画面まで&quot;">​</a></h2><ol><li><a href="/study/game/patterns/game-loop-and-update.html">ゲームループ</a>で入力・更新・描画の時間を分ける。</li><li><a href="/study/game/ecs.html">ECS</a>でID、データ配置、Query、構成変更を調べる。</li><li><a href="/study/math/rendering/transform.html">座標変換</a>と<a href="/study/graphics/pipeline/overview.html">描画パイプライン</a>から画面へつなぐ。</li><li>作って試すなら<a href="/study/game/shooter-design.html">シューティングの設計</a>を読み、<a href="/study/game/shooter-cpp.html">C++版</a>または<a href="/study/game/shooter-unity.html">Unity版</a>へ進む。</li></ol><h2 id="sendしたデータが、相手のアプリへ届くまで" tabindex="-1">sendしたデータが、相手のアプリへ届くまで <a class="header-anchor" href="#sendしたデータが、相手のアプリへ届くまで" aria-label="Permalink to &quot;sendしたデータが、相手のアプリへ届くまで&quot;">​</a></h2><ol><li><a href="/study/network/tcp-sockets.html">ソケットとTCP通信</a>で、IP・ポート、送受信バッファ、バイト列とメッセージ、半閉鎖を分ける。</li><li><a href="/study/practice/network/tcp-loopback-observation.html">C++・C#のローカル通信</a>で、長さ付きメッセージを復元し、送信停止後の応答と受信EOFを確かめる。</li><li>待機と非同期処理の基本は<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>へ進む。今回の通信例は、非ブロッキング操作とreadiness待ちを使う。</li></ol><h2 id="tcpのバイト列が、webの要求と応答になるまで" tabindex="-1">TCPのバイト列が、Webの要求と応答になるまで <a class="header-anchor" href="#tcpのバイト列が、webの要求と応答になるまで" aria-label="Permalink to &quot;TCPのバイト列が、Webの要求と応答になるまで&quot;">​</a></h2><ol><li><a href="/study/network/http-messages.html">HTTP通信</a>で、要求行、状態コード、ヘッダー、本文の形式と長さを分ける。</li><li><a href="/study/practice/network/http-message-observation.html">C++・C#のHTTP観察</a>で、ローカルのGETと応答を照合し、本文のバイト数と文字数、メッセージ完成とEOFを確かめる。</li><li>下の層から調べる場合は<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、文字の表現は<a href="/study/data/unicode-and-encoding.html">Unicodeと文字コード</a>へ戻る。</li></ol><h2 id="保存したhttp応答を、いつ再利用できるか" tabindex="-1">保存したHTTP応答を、いつ再利用できるか <a class="header-anchor" href="#保存したhttp応答を、いつ再利用できるか" aria-label="Permalink to &quot;保存したHTTP応答を、いつ再利用できるか&quot;">​</a></h2><ol><li><a href="/study/network/http-caching.html">HTTPキャッシュ</a>で、保存、freshness、再検証、Cache-Control、ETagと304の役割を調べる。</li><li><a href="/study/practice/network/http-cache-observation.html">C++・C#のHTTP再検証</a>で、ローカルサーバーへ条件付きGETを送り、304に本文がないことと、保存した本文を使う流れを確かめる。</li><li>メッセージの構造は<a href="/study/network/http-messages.html">HTTP通信</a>、本文を段階的に扱う仕組みは<a href="/study/browser/streams-backpressure.html">Streams API</a>へつなげる。</li></ol><h2 id="名前から、接続先のip候補が決まるまで" tabindex="-1">名前から、接続先のIP候補が決まるまで <a class="header-anchor" href="#名前から、接続先のip候補が決まるまで" aria-label="Permalink to &quot;名前から、接続先のIP候補が決まるまで&quot;">​</a></h2><ol><li><a href="/study/network/dns-resolution.html">DNSと名前解決</a>で、OSの名前解決、再帰リゾルバー、権威DNS、レコードとキャッシュを分ける。</li><li><a href="/study/practice/network/name-resolution-observation.html">C++・C#の名前解決観察</a>で、数値IP・localhost・追加指定する公開名を調べ、APIの結果から分かる範囲を確かめる。</li><li>IPを得た後の接続は<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、要求と応答は<a href="/study/network/http-messages.html">HTTP通信</a>へ進む。</li></ol><h2 id="httpsで暗号化し、接続相手を確かめるには" tabindex="-1">HTTPSで暗号化し、接続相手を確かめるには <a class="header-anchor" href="#httpsで暗号化し、接続相手を確かめるには" aria-label="Permalink to &quot;HTTPSで暗号化し、接続相手を確かめるには&quot;">​</a></h2><ol><li><a href="/study/network/tls-https.html">TLS・証明書・HTTPS</a>で、鍵共有、証明書、相手名の検証、暗号化したHTTPの関係を調べる。</li><li><a href="/study/practice/network/https-observation.html">C++・C#のHTTPS観察</a>で、標準の証明書検証を保ち、APIが返す接続情報とHTTP応答を確かめる。</li><li>接続先の候補は<a href="/study/network/dns-resolution.html">DNSと名前解決</a>、要求の意味は<a href="/study/network/http-messages.html">HTTP通信</a>で確認する。</li></ol><h2 id="urlを開いてからページが見えるまで" tabindex="-1">URLを開いてからページが見えるまで <a class="header-anchor" href="#urlを開いてからページが見えるまで" aria-label="Permalink to &quot;URLを開いてからページが見えるまで&quot;">​</a></h2><ol><li>通信は<a href="/study/network/dns-resolution.html">DNSと名前解決</a>、<a href="/study/network/tcp-sockets.html">TCPとソケット</a>、<a href="/study/network/http-messages.html">HTTPの要求と応答</a>、<a href="/study/network/tls-https.html">TLS・証明書・HTTPS</a>で調べる。</li><li><a href="/study/browser/rendering-journey.html">ブラウザの描画</a>で、受信したHTMLからDOM、スタイル、レイアウト、描画、合成までをつなぐ。</li><li><a href="/study/practice/browser/render-observation.html">DOMと描画の変化を観察する</a>で、幅・色・移動・透明度を変え、寸法APIとrAFで確認できる範囲を試す。</li></ol><h2 id="promiseやawaitの続きは、いつ動くのか" tabindex="-1">Promiseやawaitの続きは、いつ動くのか <a class="header-anchor" href="#promiseやawaitの続きは、いつ動くのか" aria-label="Permalink to &quot;Promiseやawaitの続きは、いつ動くのか&quot;">​</a></h2><ol><li><a href="/study/browser/event-loop-promises.html">イベントループ・Promise・async/await</a>で、同期処理、タスク、マイクロタスク、描画機会を区別する。</li><li><a href="/study/practice/browser/event-loop-observation.html">Promiseとawaitの実行順を観察する</a>で、有限のコードから実行順を記録する。timerとrAFの相対順は固定しない。</li><li>画面の更新は<a href="/study/browser/rendering-journey.html">ブラウザの描画</a>、要求の発行と完了は<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>へつなげる。</li></ol><h2 id="メイン側とは別の実行主体へ、仕事とデータを渡すには" tabindex="-1">メイン側とは別の実行主体へ、仕事とデータを渡すには <a class="header-anchor" href="#メイン側とは別の実行主体へ、仕事とデータを渡すには" aria-label="Permalink to &quot;メイン側とは別の実行主体へ、仕事とデータを渡すには&quot;">​</a></h2><ol><li><a href="/study/browser/web-workers-messages.html">Web Workerとメッセージ通信</a>で、実行の分担、メッセージの受信、コピーと転送、寿命を区別する。</li><li><a href="/study/practice/browser/worker-message-observation.html">Workerのコピー・転送・停止を観察する</a>で、16バイトの往復、バッファの切り離し、要求ID、停止と再起動を試す。</li><li>同じ実行先の続きを扱う<a href="/study/browser/event-loop-promises.html">イベントループ・Promise・async/await</a>と、共有状態を守る<a href="/study/runtime/thread-synchronization.html">スレッド同期</a>へつなげる。</li></ol><h2 id="依頼が増えたとき、workerと待ち行列をどう管理するか" tabindex="-1">依頼が増えたとき、Workerと待ち行列をどう管理するか <a class="header-anchor" href="#依頼が増えたとき、workerと待ち行列をどう管理するか" aria-label="Permalink to &quot;依頼が増えたとき、Workerと待ち行列をどう管理するか&quot;">​</a></h2><ol><li><a href="/study/browser/worker-pool-backpressure.html">Worker poolと待ち行列の制御</a>で、受付数・実行数・待機数、上流への抑制、取消しと終了を区別する。</li><li><a href="/study/practice/browser/worker-pool-observation.html">Worker poolの待機数と取消しを観察する</a>で、2実行・4待機・1拒否、待機の取消しと結果破棄による違いを確かめる。</li><li><a href="/study/browser/web-workers-messages.html">Web Workerの通信</a>でデータの受け渡しを確認し、<a href="/study/game/asset-loading.html">アセットロード</a>の段階と利用可能になる条件へつなぐ。</li></ol><h2 id="読み込みより処理が遅いとき、供給をどう抑えるか" tabindex="-1">読み込みより処理が遅いとき、供給をどう抑えるか <a class="header-anchor" href="#読み込みより処理が遅いとき、供給をどう抑えるか" aria-label="Permalink to &quot;読み込みより処理が遅いとき、供給をどう抑えるか&quot;">​</a></h2><ol><li><a href="/study/browser/streams-backpressure.html">Streams APIとストリーミング処理</a>で、chunk、queue、pull、バックプレッシャー、終了の伝播を区別する。</li><li><a href="/study/practice/browser/stream-backpressure-observation.html">Streams APIで供給と処理の速度差を観察する</a>で、有限のデータを遅いsinkへ送り、先読みと中断を確かめる。</li><li>仕事の受付数は<a href="/study/browser/worker-pool-backpressure.html">Worker pool</a>、文字の境界は<a href="/study/data/unicode-and-encoding.html">Unicodeとエンコーディング</a>、利用可能になる条件は<a href="/study/game/asset-loading.html">アセットロード</a>へつなげる。</li></ol><h2 id="ブラウザのどこへ保存し、いつまで残るのか" tabindex="-1">ブラウザのどこへ保存し、いつまで残るのか <a class="header-anchor" href="#ブラウザのどこへ保存し、いつまで残るのか" aria-label="Permalink to &quot;ブラウザのどこへ保存し、いつまで残るのか&quot;">​</a></h2><ol><li><a href="/study/browser/storage-lifetime.html">ブラウザの保存領域とデータの寿命</a>で、localStorage・IndexedDB・Cache API、保存区画、transaction、容量と保持方針を区別する。</li><li><a href="/study/practice/browser/storage-observation.html">保存・再読込・削除の観察</a>で、3方式へ固定データを保存し、ページ再読込後の読出しと専用データの削除を試す。</li><li>応答の自動的な再利用は<a href="/study/network/http-caching.html">HTTPキャッシュ</a>、Request／Responseの本文を扱う流れは<a href="/study/browser/streams-backpressure.html">Streams API</a>へつなげる。</li></ol><h2 id="通信できないとき、保存した応答をどう返すか" tabindex="-1">通信できないとき、保存した応答をどう返すか <a class="header-anchor" href="#通信できないとき、保存した応答をどう返すか" aria-label="Permalink to &quot;通信できないとき、保存した応答をどう返すか&quot;">​</a></h2><ol><li><a href="/study/browser/service-worker-offline.html">Service Workerとオフライン動作</a>で、登録・有効化・ページの制御、fetchへの介入と応答の選択を調べる。</li><li><a href="/study/practice/browser/service-worker-observation.html">Service Workerで応答元と登録状態を観察する</a>で、専用scopeの登録、固定GETの代替応答、解除と後片付けを試す。</li><li>応答の明示的な保存は<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域</a>、HTTPの再利用と再検証は<a href="/study/network/http-caching.html">HTTPキャッシュ</a>で確認する。</li></ol><h2 id="別オリジンへの通信で、応答を読めるかは何で決まるか" tabindex="-1">別オリジンへの通信で、応答を読めるかは何で決まるか <a class="header-anchor" href="#別オリジンへの通信で、応答を読めるかは何で決まるか" aria-label="Permalink to &quot;別オリジンへの通信で、応答を読めるかは何で決まるか&quot;">​</a></h2><ol><li><a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a>で、文書間の境界、応答の公開、preflightによる事前確認を区別する。</li><li><a href="/study/practice/browser/cors-observation.html">ブラウザでCORSの応答を比べる</a>で、通常ページとsandboxから同じデータをGETし、公開版とローカル配信で結果を比べる。</li><li><a href="/study/network/http-messages.html">HTTPメッセージ</a>で要求・応答を確認し、<a href="/study/network/http-caching.html">HTTPキャッシュ</a>で応答を再利用する条件へつなげる。</li></ol><h2 id="ページをまたいで、サーバーが同じセッションをどう見つけるか" tabindex="-1">ページをまたいで、サーバーが同じセッションをどう見つけるか <a class="header-anchor" href="#ページをまたいで、サーバーが同じセッションをどう見つけるか" aria-label="Permalink to &quot;ページをまたいで、サーバーが同じセッションをどう見つけるか&quot;">​</a></h2><ol><li><a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>で、Cookieを送る条件、サーバーによるIDの照合、ログアウト時の失効を区別する。</li><li><a href="/study/practice/browser/cookie-session-observation.html">Cookieの範囲とセッションIDを観察する</a>で、Pathによる見え方と、HttpOnlyのIDが次の要求に付くところを確かめる。</li><li>別オリジンでの応答の読み取りは<a href="/study/browser/same-origin-cors.html">CORS</a>、ブラウザ内でのデータ保持は<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域</a>へつなげる。</li></ol><h2 id="表示する文字列がhtmlやコードに変わるのはどこか" tabindex="-1">表示する文字列がHTMLやコードに変わるのはどこか <a class="header-anchor" href="#表示する文字列がhtmlやコードに変わるのはどこか" aria-label="Permalink to &quot;表示する文字列がHTMLやコードに変わるのはどこか&quot;">​</a></h2><ol><li><a href="/study/browser/xss-and-csp.html">XSSとCSP</a>で、入力元、HTMLとして解釈する箇所、スクリプトの実行条件を区別する。</li><li><a href="/study/practice/browser/xss-csp-observation.html">textContent・innerHTML・CSPの観察</a>で、同じ入力が文字・要素・イベント処理になる違いを確かめる。</li><li>DOMができる段階は<a href="/study/browser/rendering-journey.html">ブラウザの描画</a>、スクリプトからCookieを読める条件は<a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>へつなげる。</li></ol><h2 id="cookie付きの要求をどの条件で受理するか" tabindex="-1">Cookie付きの要求をどの条件で受理するか <a class="header-anchor" href="#cookie付きの要求をどの条件で受理するか" aria-label="Permalink to &quot;Cookie付きの要求をどの条件で受理するか&quot;">​</a></h2><ol><li><a href="/study/browser/csrf-and-request-validation.html">CSRFとリクエスト検証</a>で、Cookieが届く条件、送信元の照合、セッションとトークンの照合を区別する。</li><li><a href="/study/practice/browser/csrf-observation.html">CSRFでCookie付きの要求が届く条件を観察する</a>で、同一サイトの別オリジンからフォームを送り、受理と拒否を比べる。</li><li>Cookieの送信条件は<a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>、別オリジンの応答公開は<a href="/study/browser/same-origin-cors.html">CORS</a>で確認する。</li></ol><h2 id="ブラウザのworkerと、同じメモリを共有するには" tabindex="-1">ブラウザのWorkerと、同じメモリを共有するには <a class="header-anchor" href="#ブラウザのworkerと、同じメモリを共有するには" aria-label="Permalink to &quot;ブラウザのWorkerと、同じメモリを共有するには&quot;">​</a></h2><ol><li><a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>で、COOP・COEP・CORPと、分離状態が成立する条件を整理する。</li><li><a href="/study/practice/browser/cross-origin-isolation-observation.html">Workerへのコピーと共有メモリを観察する</a>で、4種類のヘッダー設定と、コピー・共有の結果を比べる。</li><li>データの転送は<a href="/study/browser/web-workers-messages.html">Web Workerとメッセージ通信</a>、並行処理の同期は<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>へつなげる。</li></ol><h2 id="webassemblyから整数を読み書きするには" tabindex="-1">WebAssemblyから整数を読み書きするには <a class="header-anchor" href="#webassemblyから整数を読み書きするには" aria-label="Permalink to &quot;WebAssemblyから整数を読み書きするには&quot;">​</a></h2><ol><li><a href="/study/browser/webassembly-linear-memory.html">WebAssemblyと線形メモリ</a>で、モジュールのバイナリ、インスタンス、バイト位置と境界チェックを区別する。</li><li><a href="/study/practice/browser/wasm-memory-observation.html">WebAssemblyの読み込みと線形メモリを観察する</a>で、JavaScriptとWasmから同じバイト列を読み、拡張前後のビューを比べる。</li><li>バイト列での整数の表現は<a href="/study/data/integer-bits-and-bytes.html">整数とビット・バイト</a>、Workerをまたぐ共有は<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>で確認する。</li></ol><h2 id="配列や文字列をwasmへ渡すとき、どこに何を置くか" tabindex="-1">配列や文字列をWasmへ渡すとき、どこに何を置くか <a class="header-anchor" href="#配列や文字列をwasmへ渡すとき、どこに何を置くか" aria-label="Permalink to &quot;配列や文字列をWasmへ渡すとき、どこに何を置くか&quot;">​</a></h2><ol><li><a href="/study/browser/wasm-data-and-allocation.html">WebAssemblyのデータ受け渡しとメモリ確保</a>で、ポインタと長さの単位、配置、確保位置とメモリの容量を整理する。</li><li><a href="/study/practice/browser/wasm-abi-observation.html">Wasmへ配列とUTF-8を渡す実験</a>で、実際のバイト列、アラインメントによる空き、確保失敗と拡張を観察する。</li><li>文字列のバイト表現は<a href="/study/data/unicode-and-encoding.html">Unicodeとエンコーディング</a>、メモリ確保を実行環境の内側から見る場合は<a href="/study/runtime/memory/allocation-journey.html">メモリ確保の内部</a>へつなげる。</li></ol><h2 id="_2つのworkerが同じ値を更新すると何が起きるか" tabindex="-1">2つのWorkerが同じ値を更新すると何が起きるか <a class="header-anchor" href="#_2つのworkerが同じ値を更新すると何が起きるか" aria-label="Permalink to &quot;2つのWorkerが同じ値を更新すると何が起きるか&quot;">​</a></h2><ol><li><a href="/study/browser/shared-memory-atomics.html">Web Workerと共有メモリの同期</a>で、失われた更新、不可分な加算、待機と通知を区別する。</li><li><a href="/study/practice/browser/atomics-observation.html">Workerの競合とAtomicsの待機・通知を観察する</a>で、読み取りと書き込みの順序をたどる。実際のWorkerで確認する場合はローカル配信を使う。</li><li>共有できる条件は<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>、複数の値を一緒に守る設計は<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a>で調べる。</li></ol><h2 id="固定サイズのメモリで値を順番に渡すには" tabindex="-1">固定サイズのメモリで値を順番に渡すには <a class="header-anchor" href="#固定サイズのメモリで値を順番に渡すには" aria-label="Permalink to &quot;固定サイズのメモリで値を順番に渡すには&quot;">​</a></h2><ol><li><a href="/study/browser/spsc-ring-buffer.html">リングバッファとSPSCキュー</a>で、読み書き位置が末尾から先頭に戻る仕組みと、空・満杯の判定を整理する。</li><li><a href="/study/practice/browser/ring-buffer-observation.html">リングバッファの満杯・折り返し・読み出し順を観察する</a>で、満杯で拒否された値を空きができてから入れ直し、読み出し順を比べる。</li><li>異なるWorkerへの公開順序は<a href="/study/browser/shared-memory-atomics.html">Web Workerと共有メモリの同期</a>、受付を制御する方針は<a href="/study/browser/worker-pool-backpressure.html">Worker poolとバックプレッシャー</a>へつなげる。</li></ol><h2 id="音声データが出力に間に合わないと何が起きるか" tabindex="-1">音声データが出力に間に合わないと何が起きるか <a class="header-anchor" href="#音声データが出力に間に合わないと何が起きるか" aria-label="Permalink to &quot;音声データが出力に間に合わないと何が起きるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-worklet-buffering.html">AudioWorkletと音声バッファ</a>で、サンプルフレーム、レンダリングの処理単位、データの供給不足を区別する。</li><li><a href="/study/practice/browser/audio-buffer-observation.html">AudioWorkletで先読みとアンダーランを観察する</a>で、同じ到着の遅れを与え、先読みの有無で波形と不足したフレーム数を比べる。</li><li>待ち行列で枠を使い回す仕組みは<a href="/study/browser/spsc-ring-buffer.html">リングバッファとSPSCキュー</a>で確認する。</li></ol><h2 id="複数の音を重ねると波形はどう変わるか" tabindex="-1">複数の音を重ねると波形はどう変わるか <a class="header-anchor" href="#複数の音を重ねると波形はどう変わるか" aria-label="Permalink to &quot;複数の音を重ねると波形はどう変わるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシング</a>で、音源ごとのゲイン、加算、出力までの振幅の余裕を確認する。</li><li><a href="/study/practice/browser/audio-mixing-observation.html">Web Audioでゲインとクリッピングを観察する</a>で、マスターゲインを変えてクリップ前後の波形とピークを比べる。</li><li>音声フレームの供給と出力の関係は<a href="/study/browser/audio-worklet-buffering.html">AudioWorkletと音声バッファ</a>で確認する。</li></ol><h2 id="再生中の音を急に消すと何が起きるか" tabindex="-1">再生中の音を急に消すと何が起きるか <a class="header-anchor" href="#再生中の音を急に消すと何が起きるか" aria-label="Permalink to &quot;再生中の音を急に消すと何が起きるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-gain-automation.html">Web Audioのゲインオートメーション</a>で、音声の時刻に沿ってゲインが変わる仕組みと、急な消音で生じる波形の段差を確認する。</li><li><a href="/study/practice/browser/audio-fade-observation.html">Web Audioで急な消音とフェードを観察する</a>で、フェードの長さを変え、切り替え前後のサンプル値と波形を比べる。</li><li>複数の音を足し合わせる場合のゲインは<a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシング</a>で確認する。</li></ol><h2 id="二つの音を入れ替える途中で音量はどう変わるか" tabindex="-1">二つの音を入れ替える途中で音量はどう変わるか <a class="header-anchor" href="#二つの音を入れ替える途中で音量はどう変わるか" aria-label="Permalink to &quot;二つの音を入れ替える途中で音量はどう変わるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-crossfade.html">Web Audioのクロスフェード</a>で、二つのゲインの形と、音源の相関が加算結果にどう関わるかを確認する。</li><li><a href="/study/practice/browser/audio-crossfade-observation.html">Web Audioで線形と等電力のクロスフェードを比べる</a>で、音源の組み合わせを変え、切り替え前と中点付近の実効値を比べる。</li><li>ゲインを音声の時刻で変える仕組みは<a href="/study/browser/audio-gain-automation.html">Web Audioのゲインオートメーション</a>で確認する。</li></ol><h2 id="同じ音を少し遅らせて重ねると何が起きるか" tabindex="-1">同じ音を少し遅らせて重ねると何が起きるか <a class="header-anchor" href="#同じ音を少し遅らせて重ねると何が起きるか" aria-label="Permalink to &quot;同じ音を少し遅らせて重ねると何が起きるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-comb-filter.html">Web Audioのコムフィルター</a>で、遅延した音を足すと周波数によって強め合ったり弱め合ったりする理由を確認する。</li><li><a href="/study/practice/browser/audio-comb-observation.html">Web Audioで遅延とコムフィルターを観察する</a>で、遅延時間とゲインを変え、最初にへこむ周波数を比べる。</li><li>二つの音を切り替える途中の実効値は<a href="/study/browser/audio-crossfade.html">Web Audioのクロスフェード</a>で確認する。</li></ol><h2 id="一つの音から反響を繰り返すには" tabindex="-1">一つの音から反響を繰り返すには <a class="header-anchor" href="#一つの音から反響を繰り返すには" aria-label="Permalink to &quot;一つの音から反響を繰り返すには&quot;">​</a></h2><ol><li><a href="/study/browser/audio-feedback-delay.html">Web Audioのフィードバックディレイ</a>で、出力を遅延経路に戻す接続と、繰り返すたびに振幅が小さくなる仕組みを確認する。</li><li><a href="/study/practice/browser/audio-feedback-observation.html">Web Audioで反響の間隔と減衰を観察する</a>で、遅延時間と戻すゲインを変え、反響の時刻と振幅を比べる。</li><li>遅延した入力を一度だけ重ねたときの周波数応答は<a href="/study/browser/audio-comb-filter.html">Web Audioのコムフィルター</a>で確認する。</li></ol><h2 id="インパルス応答から部屋の響きを加えるには" tabindex="-1">インパルス応答から部屋の響きを加えるには <a class="header-anchor" href="#インパルス応答から部屋の響きを加えるには" aria-label="Permalink to &quot;インパルス応答から部屋の響きを加えるには&quot;">​</a></h2><ol><li><a href="/study/browser/audio-convolution-reverb.html">Web Audioの畳み込みリバーブ</a>で、インパルス応答をずらして重ねる計算と、直接音と残響を合流させる経路を確認する。</li><li><a href="/study/practice/browser/audio-reverb-observation.html">Web Audioで畳み込みリバーブを聴き比べる</a>で、小部屋とホールを模した応答を切り替え、打音のあとに残る響きを比べる。</li><li>出力を遅延経路に戻して反響を作る方法は<a href="/study/browser/audio-feedback-delay.html">Web Audioのフィードバックディレイ</a>で確認する。</li></ol><h2 id="音源が動くと左右の出力はどう変わるか" tabindex="-1">音源が動くと左右の出力はどう変わるか <a class="header-anchor" href="#音源が動くと左右の出力はどう変わるか" aria-label="Permalink to &quot;音源が動くと左右の出力はどう変わるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-spatial-panning.html">Web Audioの音の定位と距離減衰</a>で、聞き手から見た方向と距離が、左右の出力にどう反映されるかを確認する。</li><li><a href="/study/practice/browser/audio-spatial-observation.html">Web Audioで音の方向と距離を変えて聴く</a>で、角度と距離を別々に変え、左右のゲインと聞こえ方を比べる。</li><li>部屋から返ってくる音を別の経路で加える仕組みは<a href="/study/browser/audio-convolution-reverb.html">Web Audioの畳み込みリバーブ</a>で確認する。</li></ol><h2 id="壁越しに聞こえる音は何が変わるか" tabindex="-1">壁越しに聞こえる音は何が変わるか <a class="header-anchor" href="#壁越しに聞こえる音は何が変わるか" aria-label="Permalink to &quot;壁越しに聞こえる音は何が変わるか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-occlusion.html">Web Audioの音の遮蔽</a>で、聞き手と音源の間を判定し、ゲインとローパスで壁越しの音を表す仕組みを確認する。</li><li><a href="/study/practice/browser/audio-occlusion-observation.html">Web Audioで壁越しの音量と音色を比べる</a>で、距離をそろえた二つの位置を切り替え、音量だけを下げたときと高音も弱めたときを比べる。</li><li>聞き手から見た方向と距離による処理は<a href="/study/browser/audio-spatial-panning.html">Web Audioの音の定位と距離減衰</a>で確認する。</li></ol><h2 id="扉が開いたときの音をなめらかに戻すには" tabindex="-1">扉が開いたときの音をなめらかに戻すには <a class="header-anchor" href="#扉が開いたときの音をなめらかに戻すには" aria-label="Permalink to &quot;扉が開いたときの音をなめらかに戻すには&quot;">​</a></h2><ol><li><a href="/study/browser/audio-occlusion-transition.html">Web Audioで遮蔽をなめらかに切り替える</a>で、ゲインとカットオフを同じ時刻から徐々に変える仕組みを確認する。</li><li><a href="/study/practice/browser/audio-occlusion-transition-observation.html">Web Audioで扉が開くときの音の切り替えを比べる</a>で、時定数を変え、出力波形とゲインの実測値を比べる。</li><li>遮蔽時にゲインとローパスが音へ与える影響は<a href="/study/browser/audio-occlusion.html">Web Audioの音の遮蔽</a>で確認する。</li></ol><h2 id="近づく音源と遠ざかる音源で高さが変わるのはなぜか" tabindex="-1">近づく音源と遠ざかる音源で高さが変わるのはなぜか <a class="header-anchor" href="#近づく音源と遠ざかる音源で高さが変わるのはなぜか" aria-label="Permalink to &quot;近づく音源と遠ざかる音源で高さが変わるのはなぜか&quot;">​</a></h2><ol><li><a href="/study/browser/audio-doppler.html">Web Audioでドップラー効果を再現する</a>で、音源が動くと波の山が届く間隔が変わる仕組みを確認する。</li><li><a href="/study/practice/browser/audio-doppler-observation.html">Web Audioでドップラー効果を聴き比べる</a>で、速さと進行方向を変えて、基準の440 Hzと変化後の波形を比べる。</li><li>音源の位置を左右の配分と音量に反映する方法は<a href="/study/browser/audio-spatial-panning.html">Web Audioの音の定位と距離減衰</a>で確認する。</li></ol><h2 id="目の前を通過する音を作るには" tabindex="-1">目の前を通過する音を作るには <a class="header-anchor" href="#目の前を通過する音を作るには" aria-label="Permalink to &quot;目の前を通過する音を作るには&quot;">​</a></h2><ol><li><a href="/study/browser/audio-flyby.html">Web Audioで音源の通過音を作る</a>で、一つの軌道から高さ、左右の配分、距離減衰を求める。</li><li><a href="/study/practice/browser/audio-flyby-observation.html">Web Audioで音源が通過する前後の音を比べる</a>で、通過の前後をたどりながら、音源の位置と試聴音を比べる。</li><li>音源がまっすぐ近づく場合の周波数は<a href="/study/browser/audio-doppler.html">ドップラー効果</a>、左右の配分と距離によるゲインは<a href="/study/browser/audio-spatial-panning.html">音の定位と距離減衰</a>で確認する。</li></ol><h2 id="平均60-fpsなのにカクつくとき" tabindex="-1">平均60 FPSなのにカクつくとき <a class="header-anchor" href="#平均60-fpsなのにカクつくとき" aria-label="Permalink to &quot;平均60 FPSなのにカクつくとき&quot;">​</a></h2><ol><li><a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a>で、CPU・GPUの処理時間と画面の表示間隔を区別する。</li><li><a href="/study/practice/graphics/frame-pacing-observation.html">同じ60 FPSで表示間隔を比べる</a>で、平均が同じ二つの動きと、時間ごとの長い表示間隔を比べる。</li><li><a href="/study/graphics/optimization/tools.html">デバッグ・プロファイリングツール</a>で、処理が長引いた箇所を調べるための道具を確認する。</li></ol><h2 id="gpuが描き終えた絵はいつ画面に出るか" tabindex="-1">GPUが描き終えた絵はいつ画面に出るか <a class="header-anchor" href="#gpuが描き終えた絵はいつ画面に出るか" aria-label="Permalink to &quot;GPUが描き終えた絵はいつ画面に出るか&quot;">​</a></h2><ol><li><a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a>で、描画用の画像を受け取ってから表示側が使い終えるまでを追う。</li><li><a href="/study/practice/graphics/swap-chain-observation.html">FIFO・MAILBOX・IMMEDIATEで画面の切り替わりを比べる</a>で、表示待ち、表示されずに置き換わる絵、ティアリングを観察する。</li><li><a href="/study/graphics/capstone/02-device.html">デバイス初期化と画面クリア</a>で、Vulkanで画像を取得し、描画の完了に合わせてPresentするコードを読む。</li></ol><h2 id="入力への反応が遅いときに、どこで待ったかを調べる" tabindex="-1">入力への反応が遅いときに、どこで待ったかを調べる <a class="header-anchor" href="#入力への反応が遅いときに、どこで待ったかを調べる" aria-label="Permalink to &quot;入力への反応が遅いときに、どこで待ったかを調べる&quot;">​</a></h2><ol><li><a href="/study/graphics/optimization/input-to-display-latency.html">入力から画面に出るまでの遅延</a>で、入力の取得から走査までを追い、<a href="/study/practice/graphics/input-latency-observation.html">入力遅延の実験</a>で一つ前の走査に間に合う条件を試す。</li><li><a href="/study/graphics/optimization/gpu-timestamp-queries.html">GPU時間をタイムスタンプで測る</a>で、GPUキューのどの区間を測っているかを確かめる。</li><li><a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースの寿命とフェンス</a>で、GPUが使用中の領域をCPU側で再利用できる時点を調べる。</li><li><a href="/study/graphics/optimization/pipeline-compilation-stutter.html">シェーダーコンパイルのカクつきとパイプラインキャッシュ</a>で、初回だけ起きる処理を記録し、先に準備する仕組みを読む。</li></ol><h2 id="ゲームのデータをどの構造に入れるか" tabindex="-1">ゲームのデータをどの構造に入れるか <a class="header-anchor" href="#ゲームのデータをどの構造に入れるか" aria-label="Permalink to &quot;ゲームのデータをどの構造に入れるか&quot;">​</a></h2><ol><li><a href="/study/algorithms/arrays-and-dynamic-arrays.html">配列と動的配列</a>と<a href="/study/algorithms/linked-lists.html">連結リスト</a>で、並び方、挿入・削除、再確保が参照に及ぼす影響を比べる。</li><li><a href="/study/algorithms/queues-and-deques.html">スタック・キュー・デック</a>と<a href="/study/algorithms/binary-heaps.html">二分ヒープ</a>で、追加した順や優先度から次に処理するデータを選ぶ。</li><li><a href="/study/algorithms/hash-tables.html">ハッシュ表</a>と<a href="/study/algorithms/search-trees.html">探索木</a>で、キーの一致を調べたいときと、キーの順序や範囲が必要なときの違いを確認する。</li><li><a href="/study/algorithms/sparse-sets.html">スパースセット</a>と<a href="/study/practice/algorithms/sparse-set-observation.html">IDを出し入れする実験</a>で、IDからの直接参照と、コンポーネントを詰めた走査を両立する仕組みを試す。</li><li><a href="/study/algorithms/generational-handles.html">世代付きハンドル</a>と<a href="/study/practice/algorithms/generational-handle-observation.html">スロット再利用の実験</a>で、同じIDを再利用したときに古い参照を識別する条件を確かめる。</li></ol><h2 id="近くの物体だけを調べるには" tabindex="-1">近くの物体だけを調べるには <a class="header-anchor" href="#近くの物体だけを調べるには" aria-label="Permalink to &quot;近くの物体だけを調べるには&quot;">​</a></h2><ol><li><a href="/study/algorithms/uniform-grid-and-spatial-hash.html">均等グリッドと空間ハッシュ</a>で、座標からセルを引き、複数セルに登録された物体を一度だけ検査する仕組みを読む。</li><li><a href="/study/algorithms/quadtrees-and-octrees.html">四分木と八分木</a>と<a href="/study/algorithms/bounding-volume-hierarchies.html">BVHとAABB</a>で、場所を分ける方法と、物体をグループに分けて箱で包む方法を比べる。</li><li><a href="/study/practice/algorithms/spatial-query-observation.html">範囲検索の実験</a>で、物体の配置や検索範囲を動かし、命中と詳細判定の件数を確かめる。</li></ol><h2 id="ソースコードの呼び出しを、実行時のアドレスまで追う" tabindex="-1">ソースコードの呼び出しを、実行時のアドレスまで追う <a class="header-anchor" href="#ソースコードの呼び出しを、実行時のアドレスまで追う" aria-label="Permalink to &quot;ソースコードの呼び出しを、実行時のアドレスまで追う&quot;">​</a></h2><ol><li><a href="/study/compilers/tokens-ast-and-type-checking.html">トークン・AST・型検査</a>と<a href="/study/compilers/llvm-ir-and-ssa.html">LLVM IRとSSA</a>で、ソースを解釈して中間表現にするまでを追う。</li><li><a href="/study/compilers/coff-relocations.html">COFFの再配置</a>と<a href="/study/os/pe-loading-and-imports.html">WindowsのPEローダー</a>で、リンクで埋める参照と、ロード時に決まるアドレスを調べる。</li><li><a href="/study/practice/compilers/build-artifact-observation.html">OBJ・EXE・PDBを作って読む実践</a>で、同じ関数呼び出しをOBJとEXEから確認する。</li></ol><h2 id="ゲームが止まった箇所や値を書き換えた箇所を探す" tabindex="-1">ゲームが止まった箇所や値を書き換えた箇所を探す <a class="header-anchor" href="#ゲームが止まった箇所や値を書き換えた箇所を探す" aria-label="Permalink to &quot;ゲームが止まった箇所や値を書き換えた箇所を探す&quot;">​</a></h2><ol><li><a href="/study/tools/windows/debugger-breakpoints-and-watchpoints.html">ブレークポイントとデータブレークポイント</a>で、指定した命令や、特定アドレスへの書き込みで止める。</li><li><a href="/study/tools/windows/crash-dumps-and-symbols.html">クラッシュダンプとシンボル</a>で、停止時の例外、スレッド、モジュールを確認し、対応するPDBから関数や行を調べる。</li></ol><h2 id="起動したプロセスはosとどうやり取りするか" tabindex="-1">起動したプロセスはOSとどうやり取りするか <a class="header-anchor" href="#起動したプロセスはosとどうやり取りするか" aria-label="Permalink to &quot;起動したプロセスはOSとどうやり取りするか&quot;">​</a></h2><ol><li><a href="/study/os/system-calls-and-privilege.html">システムコールとCPUの権限</a>で、同じスレッドがカーネルの処理へ入る流れを追う。</li><li><a href="/study/os/thread-scheduling.html">Windowsのスレッドスケジューリング</a>で、実行中・実行可能・待機中の違いと、CPU時間を割り当てる条件を調べる。</li><li><a href="/study/os/windows-handles.html">Windowsのハンドルとカーネルオブジェクト</a>で、操作できる対象と、別プロセスにハンドルを渡す方法を読む。</li><li><a href="/study/os/pipes-and-process-io.html">パイプと子プロセスの標準入出力</a>と<a href="/study/practice/process/windows-pipe-observation.html">パイプの終端を調べる実践</a>で、出力と終端を確認する。</li></ol><h2 id="作り方の変化を歴史から見る" tabindex="-1">作り方の変化を歴史から見る <a class="header-anchor" href="#作り方の変化を歴史から見る" aria-label="Permalink to &quot;作り方の変化を歴史から見る&quot;">​</a></h2><p><a href="/study/history/video-games.html">ビデオゲーム史</a>の作品・ハード・媒体・流通と、<a href="/study/guide/rendering/timeline.html">リアルタイム3D技術史</a>の技術の変化から、気になった仕組みへ進みます。</p>',129)])])}const f=e(l,[["render",o]]);export{c as __pageData,f as default};
